   // board must never look the same.
   const canvas = canvasState.data;
   const canvasLoading = canvasState.kind === "loading";
   const canvasError = canvasState.kind === "error" ? canvasState.error : null;

   const value = useMemo<StudioContextValue>(
     () => ({
       settings,
       saveSettings,
       displayName,
       setDisplayName,
       brief,
       saveBrief,
       setupOpen,
       openSetup,
       closeSetup,
       canvas,
       canvasLoading,
       canvasCached,
       canvasState,
       canvasError,
       refreshCanvas,
       llmHealth,
       mcpReachable,
       sidecarReachable,
+      dismissedSidecarNotice,
+      dismissSidecarNotice,
+      recheckConnections,
       checkConnections,
       messages,
       streaming,
       thinkingPhase,
       toolActivity,
       sendMessage,
       stopStreaming,
       clearChat,
       conversationId,
       memory,
       memoryLoading,
       refreshMemory,
       addObservation,
       updateObservation,
       deleteObservation,
       clearMemory,
       pushNotice,
       offlineReply,
       addStep,
       addOutcome,
       createJob,
       updateJob,
       deleteJob,
       updateStep,
       deleteStep,
       updateOutcome,
       deleteOutcome,
       activePanel,
       openPanel,
       closePanel,
       ask,
       toasts,
       pushToast,
       dismissToast,
       connectors,
       connectorsError,
       presets,
       presetError,
       refreshConnectors,
       refreshPresets,
       addConnector,
       deleteConnector,
       connectorSuggestions,
       dismissConnectorSuggestion,
       notifications,
       unreadNotificationCount,
       markNotificationAsRead,
       markAllNotificationsAsRead,
       dismissNotification,
       addNotification,
       simulateBackgroundEvent,
     }),
     [
       settings,
       saveSettings,
       displayName,
       setDisplayName,
       brief,
       saveBrief,
       setupOpen,
       openSetup,
       closeSetup,
       canvas,
       canvasLoading,
       canvasCached,
       canvasState,
       canvasError,
       refreshCanvas,
       llmHealth,
       mcpReachable,
       sidecarReachable,
+      dismissedSidecarNotice,
+      dismissSidecarNotice,
+      recheckConnections,
       checkConnections,
       messages,
       streaming,
       thinkingPhase,
       toolActivity,
       sendMessage,
       stopStreaming,
       clearChat,
       conversationId,
       memory,
       memoryLoading,
       refreshMemory,
       addObservation,
       updateObservation,
       deleteObservation,
       clearMemory,
       pushNotice,
       offlineReply,
       addStep,
       addOutcome,
       createJob,
       updateJob,
       deleteJob,
       updateStep,
       deleteStep,
       updateOutcome,
       deleteOutcome,
       activePanel,
       openPanel,
       closePanel,
       ask,
       toasts,
       pushToast,
       dismissToast,
       connectors,
       connectorsError,
       presets,
       presetError,
       refreshConnectors,
       refreshPresets,
       addConnector,
       deleteConnector,
       connectorSuggestions,
       dismissConnectorSuggestion,
       notifications,
       unreadNotificationCount,
       markNotificationAsRead,
       markAllNotificationsAsRead,
       dismissNotification,
       addNotification,
       simulateBackgroundEvent,
     ],
   );

   return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
 }

 export function useStudio(): StudioContextValue {
   const context = useContext(StudioContext);
   if (!context) {
     throw new Error("useStudio must be used within a StudioProvider");
   }
   return context;
 }

