 }

 .changelog-release__content {
   display: flex;
   flex-direction: column;
   gap: 14px;
 }

 .changelog-category__title {
   font-size: 0.82rem;
   font-weight: 700;
   text-transform: uppercase;
   letter-spacing: 0.06em;
   color: #a5b4fc;
