+  {
+    name: "remember",
+    description: "Save an observation to local memory.",
+    parameters: {
+      type: "object",
+      properties: {
+        kind: {
+          type: "string",
+          enum: [
+            "career",
+            "opportunity",
+            "business",
+            "stakeholder",
+            "constraint",
+            "evidence",
+            "preference",
+          ],
+        },
+        text: { type: "string" },
+      },
