 }

 .ui-bet__label {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-indigo);
   white-space: nowrap;
 }

 .ui-bet__value {
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 .ui-phase {
   padding: 12px;
   border-radius: 10px;
   border: 1px solid;
   min-width: 0;
 }

 .ui-phase.ui-tone--critical {
   background: rgba(248, 113, 113, 0.06);
   border-color: rgba(248, 113, 113, 0.22);
 }

 .ui-phase.ui-tone--positive {
   background: rgba(52, 211, 153, 0.06);
   border-color: rgba(52, 211, 153, 0.22);
 }

 .ui-phase__label {
   margin-bottom: 7px;
   font-size: 0.64rem;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-phase__items {
   margin: 0;
   padding-left: 16px;
   display: flex;
   flex-direction: column;
   gap: 5px;
   font-size: 0.84rem;
   color: #cbd5e1;
 }

 /* Evidence */
 .ui-quote {
   margin: 0;
   padding-left: 12px;
   border-left: 2px solid rgba(129, 140, 248, 0.5);
   font-size: 0.95rem;
   font-style: italic;
   line-height: 1.55;
   color: #e2e8f0;
 }

 /* Job map */
 .ui-jobmap {
   list-style: none;
   margin: 0;
   padding: 0;
 }

 .ui-jobmap__step {
   display: flex;
   gap: 10px;
   padding: 8px 0;
   border-bottom: 1px solid rgba(255, 255, 255, 0.04);
 }

 .ui-jobmap__step:last-child {
   border-bottom: none;
 }

 .ui-jobmap__index {
   flex: none;
   display: grid;
   place-items: center;
   width: 20px;
   height: 20px;
   border-radius: 6px;
   background: rgba(129, 140, 248, 0.14);
   color: var(--studio-indigo);
   font-size: 0.7rem;
   font-weight: 700;
   font-variant-numeric: tabular-nums;
 }

 .ui-jobmap__body {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-jobmap__name {
   font-size: 0.88rem;
 }

 .ui-jobmap__stage {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-jobmap__note {
   font-size: 0.78rem;
   color: var(--studio-muted);
 }

 /* Decision record */
 .ui-fields {
   margin: 0;
   display: flex;
   flex-direction: column;
   gap: 10px;
 }

 .ui-field {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .ui-field dt {
   font-size: 0.64rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--studio-muted);
 }

 .ui-field dd {
   margin: 0;
   font-size: 0.88rem;
   color: #e2e8f0;
 }

 @media (max-width: 640px) {
   .ui-grid--2,
   .ui-grid--3 {
     grid-template-columns: minmax(0, 1fr);
   }
 }

 @media (prefers-reduced-motion: reduce) {
   .ui-surface {
     animation: none;
   }

   .ui-meter__fill {
     transition: none;
   }
 }

 /* Markdown inside a surface. Cards are dense; paragraphs should hug. */
 .ui-card .md-paragraph,
 .ui-callout__body .md-paragraph,
 .ui-card__evidence .md-paragraph,
 .ui-quote .md-paragraph {
   margin: 0 0 6px;
 }

 .ui-card .md-paragraph:last-child,
 .ui-callout__body .md-paragraph:last-child,
 .ui-card__evidence .md-paragraph:last-child,
