 }

 .stage__thread {
   display: flex;
   flex-direction: column;
   flex: 1;
   min-width: 0;
   min-height: 0;
 }

 /* ------------------------------------------------------------------ */
 /* Rail: what the thread has made, above the thread                   */
 /* ------------------------------------------------------------------ */
 .rail {
   flex: none;
   padding: 0 22px;
 }

 .rail__list {
   display: flex;
   align-items: center;
   gap: 2px;
   width: 100%;
   max-width: 720px;
   margin: 0 auto;
   padding: 0 0 6px;
   list-style: none;
   overflow-x: auto;
